// callback_data shape: <action>_<prospect_id>. action has no underscores;
// prospect_id is a uuid (hyphens only), so split on the FIRST underscore.
const cb = $input.first().json.callback_query || {};
const data = String(cb.data || '');
const i = data.indexOf('_');
const action = i === -1 ? data : data.slice(0, i);
const pid = i === -1 ? '' : data.slice(i + 1);
const chatId = cb.message && cb.message.chat ? cb.message.chat.id : null;
return [{ json: { action, pid, chatId, cbId: cb.id } }];

// Deterministic (temp-0) renderer. Builds the requested message text, the
// tap-to-send wa.me link, and the routing mode. Refuses if suppressed/opted out.
const pc = $('Parse Callback').item.json;
let p = $('Get Prospect').item.json; if (Array.isArray(p)) p = p[0] || {};
let supp = $('Check Suppression').item.json; if (!Array.isArray(supp)) supp = supp ? [supp] : [];

const action = pc.action;
const first = (p.owner_first_name || '').trim();
const who = first || 'there';
const biz = p.business_name || 'your salon';
const SHOWCASE = 'https://booking-page-beta.vercel.app/?biz=showcase-lash-studio';

function waDigits(raw){ let d = String(raw||'').replace(/\D/g,''); if (d.startsWith('0')) d = '27' + d.slice(1); if (d.length === 9) d = '27' + d; return d; }
const phone = waDigits(p.whatsapp_e164 || p.phone_e164 || '');
const suppressed = supp.length > 0 || p.popia_optout === true;

const T = {
  cola: [
    'Hi ' + who + ", it's Christiaan from Streamline Automations.",
    'I build free online booking pages for salons here in SA, and I\'d love to set one up for ' + biz + ' at no cost.',
    'Here\'s one I made for a lash studio so you can see it: ' + SHOWCASE,
    'Mind if I send you a quick demo of your own? If you\'d rather I didn\'t message again, just reply STOP and I won\'t.'
  ].join('\n'),
  colb: [
    'Hi ' + who + ", it's Christiaan from Streamline Automations.",
    'Saw you take your bookings by DM and WhatsApp. Want a free page that does it automatically, so clients book themselves and you stop going back and forth?',
    'Here\'s one I built for a lash studio: ' + SHOWCASE,
    'Happy to make one for ' + biz + ' free. Want me to? If you\'d rather not hear from me, reply STOP and that\'s the end of it.'
  ].join('\n'),
  day4: [
    'Hi ' + who + ', Christiaan from Streamline Automations again, no pressure at all.',
    'Still happy to build ' + biz + ' a free booking page whenever suits you. Just say the word.',
    'Reply STOP if you\'d like me to leave it.'
  ].join('\n'),
  day10: [
    'Hi ' + who + ', last one from me, Christiaan at Streamline Automations.',
    'If a free booking page for ' + biz + ' is ever useful, I\'m one message away. All the best either way.',
    'Reply STOP to opt out.'
  ].join('\n')
};

let mode = 'blocked';
let text = '';
let waLink = '';
if (action === 'optout') { mode = 'optout'; }
else if (action === 'build') { mode = suppressed ? 'blocked' : 'build'; }
else if (T[action]) {
  if (suppressed) { mode = 'blocked'; }
  else if (!phone) { mode = 'nophone'; }
  else { mode = 'link'; text = T[action]; waLink = 'https://wa.me/' + phone + '?text=' + encodeURIComponent(text); }
}

let summary = '';
if (mode === 'link') {
  summary = ['Send to: ' + biz + (first ? ' (' + first + ')' : ''), 'Phone: +' + phone, '', 'Tap the button to open WhatsApp with this pre-typed. Review, then hit send:', '', text].join('\n');
} else if (mode === 'blocked') {
  summary = 'Refusing: ' + biz + ' is on the suppression list / has opted out. No send-link generated.';
} else if (mode === 'nophone') {
  summary = 'No phone number on file for ' + biz + ' — cannot build a wa.me link.';
} else if (mode === 'optout') {
  summary = biz + ' marked dead + opted out. Pending follow-ups cancelled and added to suppression list.';
} else if (mode === 'build') {
  summary = 'Building ' + biz + "'s booking page… delivery send-link will follow.";
}

return [{ json: { mode, action, pid: pc.pid, chatId: pc.chatId, cbId: pc.cbId, phone, biz, who, text, waLink, summary, reason: 'declined_optout' } }];
